-- Idempotent baseline for the schema previously created by GORM AutoMigrate.
CREATE TABLE IF NOT EXISTS users (id bigserial PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, password text NOT NULL, email_verified_at timestamptz, is_admin boolean DEFAULT false, created_at timestamptz, updated_at timestamptz, deleted_at timestamptz);
CREATE INDEX IF NOT EXISTS idx_users_deleted_at ON users(deleted_at);
CREATE TABLE IF NOT EXISTS users_images (id bigserial PRIMARY KEY, user_id bigint NOT NULL REFERENCES users(id), image text NOT NULL, created_at timestamptz, updated_at timestamptz, deleted_at timestamptz);
CREATE UNIQUE INDEX IF NOT EXISTS idx_user_images_filename ON users_images(image);
CREATE INDEX IF NOT EXISTS idx_user_images_owner_image ON users_images(user_id,image);
CREATE INDEX IF NOT EXISTS idx_users_images_deleted_at ON users_images(deleted_at);
CREATE TABLE IF NOT EXISTS upload_operations (filename varchar(128) PRIMARY KEY, user_id bigint NOT NULL, state varchar(32) NOT NULL, request_id varchar(64), size_bytes bigint NOT NULL DEFAULT 0, created_at timestamptz, updated_at timestamptz);
CREATE INDEX IF NOT EXISTS idx_upload_operations_state ON upload_operations(state);
CREATE INDEX IF NOT EXISTS idx_upload_operations_user_id ON upload_operations(user_id);
CREATE TABLE IF NOT EXISTS outbox_events (id varchar(64) PRIMARY KEY, request_id varchar(64), body text NOT NULL, attempts bigint, available_at timestamptz, published_at timestamptz, failed boolean, created_at timestamptz);
CREATE INDEX IF NOT EXISTS idx_outbox_events_request_id ON outbox_events(request_id);
CREATE INDEX IF NOT EXISTS idx_outbox_events_available_at ON outbox_events(available_at);
CREATE INDEX IF NOT EXISTS idx_outbox_events_published_at ON outbox_events(published_at);
CREATE INDEX IF NOT EXISTS idx_outbox_events_failed ON outbox_events(failed);
CREATE TABLE IF NOT EXISTS invite_codes (id bigserial PRIMARY KEY, code_hash varchar(64) NOT NULL, created_at timestamptz, expires_at timestamptz NOT NULL, access_to timestamptz NOT NULL, memory_limit bigint NOT NULL, used_at timestamptz);
CREATE UNIQUE INDEX IF NOT EXISTS idx_invite_codes_code_hash ON invite_codes(code_hash);
CREATE INDEX IF NOT EXISTS idx_invite_codes_expires_at ON invite_codes(expires_at);
CREATE INDEX IF NOT EXISTS idx_invite_codes_used_at ON invite_codes(used_at);
CREATE TABLE IF NOT EXISTS user_limits (user_id bigserial PRIMARY KEY, access_to timestamptz NOT NULL, memory_limit bigint NOT NULL, used_bytes bigint NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS idx_user_limits_access_to ON user_limits(access_to);
CREATE TABLE IF NOT EXISTS email_confirmation_codes (user_id bigserial PRIMARY KEY, code_hash text NOT NULL, expires_at timestamptz NOT NULL, attempts bigint NOT NULL, created_at timestamptz);
CREATE TABLE IF NOT EXISTS notices (id bigserial PRIMARY KEY, user_id bigint NOT NULL, access_to timestamptz NOT NULL, email text NOT NULL, attempts bigint, available_at timestamptz, sent_at timestamptz, created_at timestamptz);
CREATE UNIQUE INDEX IF NOT EXISTS notice_period ON notices(user_id,access_to);
CREATE INDEX IF NOT EXISTS idx_notices_available_at ON notices(available_at);
CREATE INDEX IF NOT EXISTS idx_notices_sent_at ON notices(sent_at);
CREATE TABLE IF NOT EXISTS deletions (filename varchar(128) PRIMARY KEY, attempts bigint, available_at timestamptz, completed_at timestamptz);
CREATE INDEX IF NOT EXISTS idx_deletions_available_at ON deletions(available_at);
CREATE INDEX IF NOT EXISTS idx_deletions_completed_at ON deletions(completed_at);
